    visited = set()
    components = []

    for r in range(H):
        for c in range(W):
            if grid[r][c] != 0 and (r, c) not in visited:
                color = grid[r][c]
                component = []
                queue = deque([(r, c, 0)])
                while queue:
                    cr, cc, d = queue.popleft()
                    if (cr, cc) in visited:
                        continue
                    visited.add((cr, cc))
                    component.append((cr, cc))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] == color and (nr,nc) not in visited:
