                depth = {'shell': len(component) if False else None}  # Complex, simplify

                components.append({'color': color, 'cells': component})

    return components

# Find separate components within same color
def get_separate_components_by_color(grid, color):
    """Split by color, then find each separate connected group"""
    cells_by_color = {}
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == color:
                cells_by_color.setdefault(color, []).append((r, c))

    visited = set()
    components = []

    for color, cells in cells_by_color.items():
        for cell in cells:
            if cell in visited:
                continue
            comp = []
            queue = deque([cell])
            while queue:
                cur = queue.popleft()
                if cur in visited:
                    continue
                visited.add(cur)
                comp.append(cur)
                r, c = cur
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]) and grid[nr][nc] == color and nr*100+nc not in visited:
                        queue.append((nr, nc))
            components.append(comp)

    return components

# Find outer boundary cells (touching bg or different non-bg)
def get_outer_cells(grid, color):
    """Get cells of color that touch something other than the same color"""
    H, W = len(grid), len(grid[0])
    outer = []
    for r in range(H):
        for c in range(W):
            if grid[r][c] == color:
                touches_other = False
                for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                    nr, nc = r + dr, c + dc
                    if nr < 0 or nr >= H or nc < 0 or nc >= W or grid[nr][nc] != color:
                        touches_other = True
                        break
                if touches_other:
                    outer.append((r, c))
    return outer

