# Key idea: Each position in the depth hierarchy gets assigned a different color
# based on the reversed sequence

def get_hierarchies(grid):
    """Get all connected components with their depth-order color sequence"""
    H, W = len(grid), len(grid[0])
    visited = set()
    hierarchies = []

    for r in range(H):
        for c in range(W):
            if grid[r][c] != 0 and (r, c) not in visited:
                # Find all cells in this component
                component_cells = []
                queue = deque([(r, c)])
                while queue:
                    curr = queue.popleft()
                    if curr in visited:
                        continue
                    visited.add(curr)
                    component_cells.append(curr)
                    cr, cc = curr
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] != 0 and (nr, nc) not in visited:
                            queue.append((nr, nc))

                # Now compute depth for each cell in this component
                # shell 0 = outermost (touches bg or border or different non-bg color)
                depths = {}
                from collections import deque as dq
                outer_cells = set()
                for cell in component_cells:
                    rr, cc = cell
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = rr + dr, cc + dc
                        if nr < 0 or nr >= H or nc < 0 or nc >= W or grid[nr][nc] == 0 or (nr, nc) not in component_cells:
                            outer_cells.add(cell)
                            break

                queue = dq([(cr, cc, 0) for cr, cc in outer_cells])
                while queue:
                    cr, cc, d = queue.popleft()
                    if (cr, cc) in depths:
                        continue
                    depths[(cr, cc)] = d
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < H and 0 <= nc < W and (nr, nc) in component_cells and (nr, nc) not in depths:
                            queue.append((nr, nc, d + 1))

                # Get colors at each depth and sort by depth
                depths_by_color = {}
                for cell, depth in depths.items():
                    color = grid[cell[0]][cell[1]]
                    if color not in depths_by_color:
                        depths_by_color[color] = []
                    depths_by_color[color].append((cell, depth))

                # Build color sequence by depth
                # depth_count[d] = list of colors at depth d
                depth_count = {}
                for color, cells in depths_by_color.items():
                    for _, d in cells:
                        if d not in depth_count:
                            depth_count[d] = []
                        depth_count[d].append(color)

                # Sort colors by their presence at lower depths (outermost first)
                # A color "earlier" if it appears at depth 0
                max_depth = max(depth_count.keys()) if depth_count else 0
                color_sequence = []
                for d in range(max_depth + 1):
                    colors_at_depth = set(depth_count.get(d, []))
                    if d not in color_sequence:
                        color_sequence.append(colors_at_depth)

                hierarchies.append({
                    'cells': component_cells,
                    'depths': depths,
                    'depth_count': depth_count,
                    'color_sequence': color_sequence
                })

    return hierarchies, visited

