from collections import deque

def find_single_component(grid, start_cell, mask=None):
    """Find a single connected component from start_cell (4-connectivity for any non-bg)"""
    H, W = len(grid), len(grid[0])

    cell, (r, c) = start_cell, start_cell
    component = []
    visited = set()
    queue = deque([start_cell])

    while queue:
        curr = queue.popleft()
        if curr in visited:
            continue
        visited.add(curr)
        component.append(curr)

        cr, cc = curr
        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
            nr, nc = cr + dr, cc + dc
            if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] != 0 and (nr, nc) not in visited:
                queue.append(((nr, nc), (nr, nc)))

    return component

def find_hierarchies(grid):
    H, W = len(grid), len(grid[0])
    visited_global = set()
    hierarchies = []

    for r in range(H):
        for c in range(W):
            if grid[r][c] != 0 and (r,c) not in visited_global:
                # Find all non-bg cells reachable from (r,c)
                component_cells = []
                queue = deque([(r,c)])
                while queue:
                    curr = queue.popleft()
                    if curr in visited_global:
                        continue
                    visited_global.add(curr)
                    component_cells.append(curr)

                    cr, cc = curr
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] != 0 and (nr, nc) not in visited_global:
                            queue.append((nr, nc))

                # Compute depths within this component
                depths = {}
                outer_cells = set()

                for cell in component_cells:
                    rr, cc = cell
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = rr + dr, cc + dc
                        if nr < 0 or nr >= H or nc < 0 or nc >= W or grid[nr][nc] == 0 or (nr, nc) not in component_cells:
                            outer_cells.add(cell)
                            break

                # BFS from outer cells
                queue = deque([(cr, cc, 0) for cr, cc in outer_cells])
                while queue:
                    cr, cc, d = queue.popleft()
                    if (cr, cc) in depths:
                        continue
                    depths[(cr, cc)] = d
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < H and 0 <= nc < W and (nr, nc) in component_cells and (nr, nc) not in depths:
                            queue.append((nr, nc, d + 1))

                # Get color sequence by depth
                depth_colors = {}
                for cell, depth in depths.items():
                    grid_val = grid[cell[0]][cell[1]]
                    if depth not in depth_colors:
                        depth_colors[depth] = set()
                    depth_colors[depth].add(grid_val)

                sorted_depths = sorted(depth_colors.keys())
                color_sequence = [list(depth_colors[d]) for d in sorted_depths]

                hierarchies.append({
                    'cells': component_cells,
                    'depths': depths,
                    'color_sequence': color_sequence,
                    'total_cells': len(component_cells)
                })

    return hierarchies

