# The key insight is to count depth from INNERMOST to OUTERMOST
# Instead of counting from outer cells, we need to count from inner vertices (local 4-vertex)

def transform(grid):
    from collections import deque, Counter

    H, W = len(grid), len(grid[0])
    visited_global = set()

    output = [[0]*W for _ in range(H)]

    for r in range(H):
        for c in range(W):
            if grid[r][c] != 0 and (r,c) not in visited_global:
                component_cells = []
                queue = deque([(r,c)])
                while queue:
                    curr = queue.popleft()
                    if curr in visited_global:
                        continue
                    visited_global.add(curr)
                    component_cells.append(curr)

                    cr, cc = curr
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < H and 0 <= nc < W and grid[nr][nc] != 0 and (nr, nc) not in visited_global:
                            queue.append((nr, nc))

                # Compute depths from INNERMOST (local 4-vertex) to OUTERMOST
                depths = {}
                severity_map = {}  # track which cells reach max depth

                # Add all non-border cells to severity_map initially
                for cell in component_cells:
                    rr, cc = cell
                    severity_map[cell] = {'hit': False, 'neighbor': None}

                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = rr + dr, cc + dc
                        if nr < 0 or nr >= H or nc < 0 or nc >= W or grid[nr][nc] == 0 or (nr, nc) not in component_cells:
                            severity_map[cell]['hit'] = True
                            severity_map[cell]['neighbor'] = (nr, nc)
                            break

                # Process from lowest severity (outer) to highest (inner)
                # First, add "outer" cells with severity 0
                outer_sev_cells = set()
                for cell, info in severity_map.items():
                    if info['hit']:
                        outer_sev_cells.add(cell)

                processed_sev = []

                while outer_sev_cells:
                    outer_sev = sorted(list(outer_sev_cells))
                    processed_sev.append(outer_sev)

                    # Mark neighbors of these as next severity
                    for cell in outer_sev:
                        cr, cc = cell
                        if (cr, cc) in depths:
                            continue

                        depths[(cr, cc)] = 0

                    for cell in outer_sev:
                        cr, cc = cell
                        for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                            nr, nc = cr + dr, cc + dc
                            if 0 <= nr < H and 0 <= nc < W and (nr, nc) in component_cells and (nr, nc) not in depths and not severity_map[(nr, nc)]['hit']:
                                severity_map[(nr, nc)]['neighbor'] = cell

                    # Now find next batch of outer cells
                    next_sev_cells = set()
                    for cell, info in severity_map.items():
                        if not info['hit'] and (info['neighbor'] in depths):
                            next_sev_cells.add(cell)

                    outer_sev_cells = next_sev_cells

                # Now assign depths (counting cells in processed_sev lists)
                # The first N cells (sorted) form depth 0
                # The next N cells form depth 1, etc.
                sorted_all_cells = sorted(component_cells)

                # Rebuild depths by iterating through all cells and computing their "step" from outermost
                outer_cells_batch = set()
                for cell in sorted_all_cells:
                    rr, cc = cell
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = rr + dr, cc + dc
                        if nr < 0 or nr >= H or nc < 0 or nc >= W or grid[nr][nc] == 0 or (nr, nc) not in component_cells:
                            outer_cells_batch.add(cell)
                            break

                depths = {}
                queue = deque([(cr, cc, 0) for cr, cc in outer_cells_batch])
                visited_batch = set()

                while queue:
                    cr, cc, d = queue.popleft()
                    if (cr, cc) in visited_batch:
                        continue
                    visited_batch.add((cr, cc))
                    depths[(cr, cc)] = d

                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < H and 0 <= nc < W and (nr, nc) in component_cells and (nr, nc) not in visited_batch:
                            queue.append((nr, nc, d + 1))

                # Check for overlap
                print(f"Component {sorted_all_cells[0]}: {len(component_cells)} cells")
                print(f"  Depths: {set(depths.values())}")
                for cell in sorted_all_cells[:5]:
                    print(f"    {cell}: depth={depths.get(cell, 'MISSING')}")

                # Get colors at each depth
                depth_colors = {}
                for d in set(depths.values()):
                    depth_colors[d] = set()
                for cell, d in depths.items():
                    depth_colors[d].add(grid[cell[0]][cell[1]])

                sorted_depths = sorted(depth_colors.keys())
                depth_colors_sorted = {d: sorted(list(depth_colors[d])) for d in sorted_depths}

                # Map: depth d → color at depth (N-1-d), preserving inner→outer order
                # Sort depths from INNERMOST to OUTERMOST first, then reverse
                # Actually: if outer is depth 0 and inner is max depth
                # Then output at depth d = input color at depth (N-1-d)
                # Where depth 0 is OUTER and max depth is INNER

                # Reversed color sequence (from inner to outer)
                reversed_depth_colors = [depth_colors_sorted[d] for d in reversed(sorted_depths)]

                for d in sorted_depths:
                    reversed_d = len(sorted_depths) - 1 - d
                    output_colors = reversed_depth_colors[reversed_d]
                    first_color = output_colors[0]
                    for cell in sorted_all_cells:
                        if depths.get(cell) == d:
                            output[cell[0]][cell[1]] = first_color

    return output

