                component = []
                stack = [(i, j)]
                while stack:
                    x, y = stack.pop()
                    if (x, y) not in visited:
                        visited.add((x, y))
                        component.append((x, y, color))
                        for dx, dy in [(0,1), (0,-1), (1,0), (-1,0)]:
